function isLikelyLeaking(samples) {
  if (samples.length < 2) return false;
  for (let i = 1; i < samples.length; i++) {
    if (samples[i] < samples[i - 1]) return false;
  }
  return samples[samples.length - 1] > samples[0];
}

function maxRecursionDepth(frameSizeBytes, stackLimitKB) {
  const stackLimitBytes = stackLimitKB * 1024;
  return Math.floor(stackLimitBytes / frameSizeBytes);
}

