function requiredStackKB(frameSizeBytes, targetDepth) {
  const totalBytes = frameSizeBytes * targetDepth;
  return Math.ceil(totalBytes / 1024);
}

function buildProcessTree(processes) {
  const tree = {};
  for (const { pid, ppid } of processes) {
    if (ppid === null || ppid === undefined) continue;
    if (!tree[ppid]) tree[ppid] = [];
    tree[ppid].push(pid);
  }
  return tree;
}

function findOrphans(processes, alivePids) {
  return processes
    .filter((p) => p.ppid !== null && p.ppid !== undefined && !alivePids.has(p.ppid))
    .map((p) => p.pid);
}
